      "arFull": "وَقَالُوْا قُلُوْبُنَا فِیْۤ اَكِنَّةٍ مِّمَّا تَدْعُوْنَاۤ اِلَیْهِ وَفِیْۤ اٰذَانِنَا وَقْرٌ وَّمِنْ بَیْنِنَا وَبَیْنِكَ حِجَابٌ فَاعْمَلْ اِنَّنَا عٰمِلُوْنَ ۟",
