      "number": 7,
      "arFull": "الَّذِیْنَ لَا یُؤْتُوْنَ الزَّكٰوةَ وَهُمْ بِالْاٰخِرَةِ هُمْ كٰفِرُوْنَ ۟",
      "ur": "جو زکوٰة نہیں دیتے[1] اورآخرت کے بھی منکر ہی رہتے ہیں.",
