      "footnotesUr": "[1] یہ سورت مکی ہے۔ زکوٰۃ ہجرت کے دوسرے سال فرض ہوئی۔ اس لیے اس سے مراد یاتو صدقات ہیں جس کا حکم مسلمانوں کو مکے میں بھی دیا جاتا رہا، جس طرح پہلے صرف صبح و شام کی نماز کا حکم تھا، پھرہجرت سے ڈیڑھ سال قبل لیلہ الاسراء کو پانچ فرض نمازوں کاحکم ہوا۔ یا پھر زکوٰۃ سے یہاں مراد کلمۂ شہادت ہے، جس سے نفس انسانی شرک کی آلودگیوں سے پاک ہو جاتا ہے۔ (ابن کثیر)",
