      "ur": "اللہ کے دشمنوں کی سزا یہی دوزح کی آگ ہے جس میں ان کا ہمیشگی کا گھر ہے (یہ) بدلہ ہے ہماری آیتوں سے انکار کرنے کا.[1]",
      "en": "That is the recompense of the enemies of Allāh - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting.",
      "footnotesUr": "[1] آیتوں سے مراد جیسا کہ پہلے بھی بتلایا گیا ہے، وہ دلائل و براہین واضحہ ہیں جو اللہ تعالیٰ انبیا پر نازل فرماتا ہے یا وہ معجزات ہیں جو انہیں عطا کیے جاتے ہیں یا وہ دلائل تکوینیہ ہیں جوکائنات یعنی آفاق و انفس میں پھیلے ہوئے ہیں۔ کافر ان سب ہی کا انکار کرتے ہیں، جس کی وجہ سے وہ ایمان کی دولت سے محروم رہتے ہیں۔",
