      "arFull": "وَمَنْ اَحْسَنُ قَوْلًا مِّمَّنْ دَعَاۤ اِلَی اللّٰهِ وَعَمِلَ صَالِحًا وَّقَالَ اِنَّنِیْ مِنَ الْمُسْلِمِیْنَ ۟",
