      "number": 52,
      "arFull": "قُلْ اَرَءَیْتُمْ اِنْ كَانَ مِنْ عِنْدِ اللّٰهِ ثُمَّ كَفَرْتُمْ بِهٖ مَنْ اَضَلُّ مِمَّنْ هُوَ فِیْ شِقَاقٍ بَعِیْدٍ ۟",
      "ur": "آپ کہہ دیجئے! کہ بھلا یہ تو بتاؤ کہ اگر یہ قرآن اللہ کی طرف سے آیا ہوا ہو پھر تم نے اسے نہ مانا بس اس سے بڑھ کر بہکا ہوا کون ہوگا[1] جو مخالفت میں (حق سے) دور چلا جائے.[2]",
      "en": "Say, \"Have you considered: if it [i.e., the Qur’ān] is from Allāh and you disbelieved in it, who would be more astray than one who is in extreme dissension?\"",
      "footnotesUr": "[1] یعنی ایسی حالت میں تم سے زیادہ گمراہ اور تم سے زیادہ دشمن کون ہوگا۔\n[2] شِقَاقٍ کے معنی ہیں، ضد، عناد اور مخالفت۔ بَعِيدٍ مل کر اس میں اور مبالغہ ہوجاتا ہے۔ یعنی جو بہت زیادہ مخالف اور عناد سے کام لیتا ہے، حتیٰ کہ اللہ کے نازل کردہ قرآن کی بھی تکذیب کر دیتا ہے، اس سے بڑھ کر گمراہ اور بدبخت کون ہوسکتا ہے؟",
      "footnotesEn": null,
